// Extract tenant's external labels from hashring configs.
// If one tenant appears in multiple hashring configs,
// only the external label set from the first hashring config is applied.
if externalLabels, ok := t.externalLabelsForTenant(tenantID); ok {
	var err error
	lset, err = parseAndExtendSortedLabels(lset, externalLabels, t.logger)
	if err != nil {
		return errors.Wrap(err, "failed to parse external labels for tenant "+tenantID)
	}
}

func (t *MultiTSDB) externalLabelsForTenant(tenantID string) ([]string, bool) {
	for _, hc := range t.hashringConfigs {
		if slices.Contains(hc.Tenants, tenantID) {
			return hc.ExternalLabels, true
		}
	}
	return nil, false
}

